// Reader for map.bin (generated by tools/build_map.py).
// Pure C, no ESP-IDF dependency (host-testable).
//
// File layout, all integers little-endian, coordinates in microdegrees:
//   header   : char magic[4] = "TSM1"; u32 n_lines, n_points, n_airports, n_runways   (20 bytes)
//   lines    : n_lines    x { i32 min_lat, min_lon, max_lat, max_lon;
//                             u32 first_point, n_points; u8 kind; u8 pad[3] }         (28 bytes)
//   points   : n_points   x { i32 lat, lon }                                          (8 bytes)
//   airports : n_airports x { char icao[4]; i32 lat, lon; u8 size; u8 pad[3] }        (16 bytes)
//   runways  : n_runways  x { i32 lat1, lon1, lat2, lon2 }                            (16 bytes)
#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

enum { MAP_LINE_COAST = 0, MAP_LINE_BORDER = 1 };
enum { MAP_AIRPORT_MEDIUM = 0, MAP_AIRPORT_LARGE = 1 };

typedef struct {
    const uint8_t *lines, *points, *airports, *runways;
    uint32_t n_lines, n_points, n_airports, n_runways;
} mapdata_t;

typedef struct {
    int32_t min_lat, min_lon, max_lat, max_lon; // bounding box of the polyline
    uint32_t first_point, n_points;             // slice of the points table
    uint8_t kind;                               // MAP_LINE_*
} map_line_t;

typedef struct {
    int32_t lat, lon;
} map_point_t;

typedef struct {
    char icao[5]; // NUL-terminated
    int32_t lat, lon;
    uint8_t size; // MAP_AIRPORT_*
} map_airport_t;

typedef struct {
    int32_t lat1, lon1, lat2, lon2; // the two runway ends
} map_runway_t;

// Checks the magic and that len matches the counts in the header exactly.
// The blob must outlive *map. Returns false (and leaves *map unusable) otherwise.
bool mapdata_open(mapdata_t *map, const void *blob, size_t len);

// Accessors. The index must be below the matching count.
// The blob may be unaligned.
map_line_t mapdata_line(const mapdata_t *map, uint32_t i);
map_point_t mapdata_point(const mapdata_t *map, uint32_t i);
map_airport_t mapdata_airport(const mapdata_t *map, uint32_t i);
map_runway_t mapdata_runway(const mapdata_t *map, uint32_t i);

// Index of the airport with this ICAO code (case-insensitive), or -1.
int mapdata_find_airport(const mapdata_t *map, const char *icao);
